using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HeveliusHeveliusLinkEffect", menuName = "Data/Battle/Effects/Hevelius/HeveliusHeveliusLink Effect")]
public class HeveliusHeveliusLinkEffect : Effect
{
	private const string linkEffectStayActiveID = "LinkEffectStayActive";

	[Header("Link Effect")]
	[SerializeField]
	private Effect heveliusLinkEffect;

	[Header("Achievement")]
	[SerializeField]
	private AchievementData mechanicIntegrationAchievementData;

	[SerializeField]
	private LacertianBeamAction fusionBeamAction;

	public Effect HeveliusLinkEffect => heveliusLinkEffect;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return heveliusLinkEffect.GetEffectDescription(amount) + GetEffectStayActiveDescription() + AppendedDescription();
	}

	protected string GetEffectStayActiveDescription()
	{
		return "\n" + base.localizationManager.GetLocalizedString("LinkEffectStayActive");
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (!(this is BoostHeveliusHeveliusLinkEffect))
		{
			heveliusLinkEffect.Initialize(effectAmount, effectOwner, source);
		}
		CheckMechanicIntegrationAchievement();
	}

	private void CheckMechanicIntegrationAchievement()
	{
		if (!mechanicIntegrationAchievementData.IsUnlocked() && fusionBeamAction.GetLinkAmount() >= mechanicIntegrationAchievementData.AchievementVariableAmount * 2)
		{
			mechanicIntegrationAchievementData.Unlock();
		}
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (!(this is BoostHeveliusHeveliusLinkEffect))
		{
			heveliusLinkEffect.EffectIncreased(effectAmount, effectOwner, source);
		}
		CheckMechanicIntegrationAchievement();
	}

	public override void EffectDecreased(int effectAmount, GameObject effectOwner)
	{
		if (!(this is BoostHeveliusHeveliusLinkEffect))
		{
			heveliusLinkEffect.EffectDecreased(effectAmount, effectOwner);
		}
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (!(this is BoostHeveliusHeveliusLinkEffect))
		{
			heveliusLinkEffect.ActivateEffect(effectAmount, effectOwner);
		}
		return effectAmount;
	}

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (!(this is BoostHeveliusHeveliusLinkEffect))
		{
			heveliusLinkEffect.ActivateEffectWithSource(effectAmount, effectOwner, source);
		}
		return effectAmount;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		if (!(this is BoostHeveliusHeveliusLinkEffect))
		{
			heveliusLinkEffect.RemoveEffect(effectAmount, effectOwner);
		}
	}
}
